public class Main {
    public static void main(String[] args) {
        new Siswa("Budi");
        new Siswa("Sari");
        new Siswa("Andi");

        System.out.println("Total siswa: " + Siswa.jumlah);
        System.out.println(Hitung.kuadrat(6));
    }
}

class Siswa {
    static int jumlah = 0;
    String nama;

    Siswa(String nama) {
        this.nama = nama;
        jumlah++;
    }
}

class Hitung {
    static int kuadrat(int n) {
        return n * n;
    }
}

