public class Main {
    public static void main(String[] args) {
        new Counter();
        new Counter();
        new Counter();
        new Counter();
        System.out.println("Total: " + Counter.total);
    }
}

class Counter {
    static int total = 0;

    Counter() {
        total++;
    }
}
